/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, FiniteExtension, Mul, NotImplementedError, NotInvertible, Poly, Pow, QQ, Sym, add, isUnsolved, mul, pow, rational, symbols } from '../../../src';
import { at, sympyMatches, sympyStr } from '../../sympy-str';
import { equivalent } from '../../sympy-equivalent';

describe("doctests of sympy.polys.agca.extensions", () => {
  it("R.rank", () => {
    const x = new Sym('x');
    expect(sympyStr(new FiniteExtension(Poly.from(add(-2, pow(x, 2)), [x], { domain: 'ZZ', pure: false })).rank)).toBe('2');
  });
  it("R(1 + x)*(3 - 2*x)", () => {
    const x = new Sym('x');
    expect(sympyStr(new FiniteExtension(Poly.from(add(-2, pow(x, 2)), [x], { domain: 'ZZ', pure: false })).convert(add(1, x)).mul(add(3, mul(-2, x))))).toBe('x - 1');
  });
  it("F.basis", () => {
    const x = new Sym('x');
    expect(sympyMatches([at(new FiniteExtension(Poly.from(add(2, pow(x, 2), pow(x, 3)), [x], { domain: 'GF(5)', pure: false })).basis, 0), at(new FiniteExtension(Poly.from(add(2, pow(x, 2), pow(x, 3)), [x], { domain: 'GF(5)', pure: false })).basis, 1), at(new FiniteExtension(Poly.from(add(2, pow(x, 2), pow(x, 3)), [x], { domain: 'GF(5)', pure: false })).basis, 2)], '(1, x, x**2)')).toBe(true);
  });
  it("F(x + 3)/(x**2 + 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new FiniteExtension(Poly.from(add(2, pow(x, 2), pow(x, 3)), [x], { domain: 'GF(5)', pure: false })).convert(add(-2, x)).div(add(2, pow(x, 2))))).toBe('-2*x**2 + x + 2');
  });
  it("FiniteExtension(Poly(t**2 - x**3 - x + 1, t, field=True))", () => {
    const [t, x] = symbols('t x');
    expect(sympyStr(new FiniteExtension(Poly.from(add(1, pow(t, 2), mul(-1, x), mul(-1, pow(x, 3))), [t], { domain: 'ZZ(x)', pure: false })))).toBe('ZZ(x)[t]/(t**2 - x**3 - x + 1)');
  });
});

